-- new
-- OuroFlow UI - Crimson Red + Lucide Icons Only

local LucideModule = nil
do
    local urls = {
        "https://raw.githubusercontent.com/mstudio45/lucide-roblox-direct/refs/heads/main/source.lua",
        "https://raw.githubusercontent.com/mstudio45/lucide-roblox-direct/main/source.lua",
    }
    if type(isfile) == "function" and type(readfile) == "function" then
        pcall(function()
            if isfile("OuroFlow/lucide.lua") then
                local ok, mod = pcall(function() return loadstring(readfile("OuroFlow/lucide.lua"))() end)
                if ok and type(mod) == "table" and mod.GetAsset then LucideModule = mod end
            end
        end)
    end
    if not LucideModule then
        for _, url in ipairs(urls) do
            local ok, mod = pcall(function() return loadstring(game:HttpGet(url))() end)
            if ok and type(mod) == "table" and mod.GetAsset then
                LucideModule = mod
                if type(writefile) == "function" and type(makefolder) == "function" and type(isfolder) == "function" then
                    pcall(function()
                        if not isfolder("OuroFlow") then makefolder("OuroFlow") end
                        writefile("OuroFlow/lucide.lua", game:HttpGet(url))
                    end)
                end
                break
            end
        end
    end
    if LucideModule then print("[OuroFlow] Lucide Icons geladen: OK")
    else warn("[OuroFlow] Lucide Icons NICHT geladen") end
end

local BundledSteelIcons = setmetatable({}, {
    __index = function(_, key)
        if LucideModule and LucideModule.GetAsset then
            local ok, data = pcall(LucideModule.GetAsset, key)
            if ok and data then return data end
        end
        return nil
    end,
})

